(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sr"] = {"ui":{"skip":"Пређи на садржај","back":"← Назад на AI-gile","lang.button":"Језик: {name}","lang.dialog":"Изабери језик","lang.search":"Претражи језике","lang.none":"Ниједан језик не одговара","lang.notYet":"{name} још није преведен","theme.aria":"Промени тему: светла, тамна или црна","theme.toLight":"Пређи на светлу тему","theme.toDark":"Пређи на тамну тему","theme.toBlack":"Пређи на црну тему (права црна, пријатна за OLED екране)","words.underline":"Подвуци ове речи на страници","words.underlineHelp":"Пређи мишем преко истачкане речи или је додирни да видиш шта значи.","words.col.todo":"Картице изабране за сада: тим следеће почиње с њима.","words.col.doing":"Један AI управо ради на овој картици.","words.col.review":"Један AI је завршио посао; други га проверава пре него што стигне до тебе.","words.col.verify":"Чека тебе: пробај и реци да ли ради.","words.col.team":"Твоје белешке или одговори, који чекају да их тим преузме.","words.col.done":"Завршено и прихваћено.","index.title":"AI-gile: твој AI тим програмера на једној табли","index.description":"AI-gile је канбан табла за AI тимове који пишу код. Они раде док ти спаваш; ти добијеш једну кратку гомилу ствари да одлучиш, тестираш и прихватиш.","hero.logoAlt":"Икона AI-gile табле","hero.h1.html":"Твој AI тим програмера на једној&nbsp;табли.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовршено: хвала што пробаш!","hero.lede":"Они граде док ти спаваш. Будиш се уз једну кратку гомилу: пар питања, пар ствари за тест, један или два љубичаста дијаманта. Кликни, прихвати, и назад на кафу.","dl.windows":"Windows апликација","dl.browser":"Покрени у прегледачу","dl.messenger":"📱 Messenger за твој телефон","dl.soon":"Ускоро","dl.notify":"🔔 Јави ми кад се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, али тиму никад не треба кафа за стендап. (Стендап ипак држе.)","pitch.h2":"AI-gile у онолико речи колико хоћеш","pitch.lede":"Изабери дужину, од једне речи до 144. Свака дужина је посебан опис, написан баш за ту величину. Повуци клизач или користи стрелице.","pitch.rangeLabel":"Дужина у речима","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} реч","pitch.words.other":"{n} речи","pitch.letters.one":"{n} слово","pitch.letters.other":"{n} слова","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знакова","count.line.html.one":"{n} картица на табли управо сад","count.line.html.other":"{n} картица на табли управо сад","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} људи","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агената","people.working.html.one":"⚡ {n} на послу управо сад","people.working.html.other":"⚡ {n} на послу управо сад","pre.title":"AI-gile: овде се нешто гради","pre.description":"Овде се нешто гради: табла на којој AI тимови граде оно што тражиш и уче те успут. За сада затворена пре-алфа са пријатељима.","pre.h1":"Овде се нешто гради. 🤫","pre.line":"Табла на којој AI тимови граде оно што тражиш и уче те успут. За сада затворена пре-алфа са пријатељима.","pre.btn":"🔔 Јави ми кад се отвори","pre.peek":"Иза стакла: права табла, уживо. Свака картица је обојена трака.","pre.peekFake":"Иза стакла: овако изгледа табла на делу.","pre.night":"🌙 Ноћни чувар је задужен · 😴 човек се одмара","features.aria":"Шта ради","f.pile.h":"Једна гомила за тебе","f.pile.html":"<b>За тебе</b> држи све што чека тебе, преко свих пројеката: питања, ствари за тест, задатке које може само човек. Твој ред каже шта је следеће и колико траје.","f.sleep.h":"Тимови који раде док ти спаваш","f.sleep.p":"Сваки пројекат има вођу и тим AI агената. Коментариши картицу и тим се буди, одради посао и врати је са корацима које може да прати и уморан човек.","f.tester.h":"AI тестер проверава први","f.tester.p":"Пре него што нешто стигне до тебе, тестер прати кораке у копији апликације и показује шта је видео, са снимком екрана. Прелистај оне који су прошли и прихвати једним кликом.","f.proof.h":"Докази, не обећања","f.proof.p":"Свака предаја показује шта се променило: фајлове, разлику, снимке екрана. Не мораш да отвараш сваку апликацију да видиш да ли је готово.","f.chat.h":"Ћаскај са својим вођама","f.chat.p":"Трака као на Discordu: једна икона по пројекту, љубичасти дијаманти за оно што треба тебе. Пошаљи вођи идеју; он је претвори у картице и план, са дугметом ✅ Крени.","f.tidy.h":"Сама се сређује","f.tidy.p":"Сродне картице се спајају у једну, збркани наслови се поправљају, а провера токена држи код сажетим. Мање ствари између којих се пребацујеш, мање мисли.","f.private.h":"Твоје, на твом рачунару","f.private.li1":"Табла ради на твом рачунару и одговара само теби.","f.private.li2":"Приватне поруке међу људима су шифроване од краја до краја.","f.private.li3":"Без налога, без трагача, без колачића.","f.lang.h":"На твом језику","f.lang.p":"Преко 120 језика, од холандског, велшког и јапанског до гусарског, Јоде и клингонског, уз брзи повратак на енглески за стручне изразе.","f.service.h":"Од идеје до правог сервиса","f.service.p":"Направио си нешто са AI што људи сада користе? Означи то као сервис и табла ти помаже да га добро водиш: провере доступности, јавна страница статуса, инциденти са анализом, измене којима треба Go, резервне копије проверене сваки дан. Помоћ те учи сваки корак док радиш.","msgr.h2":"AI-gile Messenger: твој тим у џепу","msgr.p1":"Разговарај са својим AI тимом без отварања табле. Ћаскај са вођама пројеката и пријатељима, погледај кораке за тестирање картице и одговори на њих, све са телефона.","msgr.p2":"Да га повежеш, скенирај QR код на својој табли. Први пут? Пријатељско демо ћаскање ће ти све показати.","msgr.when":"Прво Android, затим веб верзија за телефоне и iPhone.","msgr.who":"Твој вођа пројекта","msgr.b1":"Исправка тамног режима је спремна. Хоћеш кораке за тестирање?","msgr.b2":"Да, молим!","msgr.b3":"1. Отвори Подешавања. 2. Изабери Тамно. Да ли изгледа како треба?","tl.aria":"Временска линија од првог разговора до плана","tl.h2":"Од првог ћаскања до онога што следи","tl.lede":"Прави датуми и сати, у твојој временској зони. После данас то је план, без обећаних датума.","tl.today":"Данас","tl.planned":"планирано","tl.doing":"у току","tl.cards.one":"{n} картица","tl.cards.other":"{n} картица","join.h2":"Придружи се","join.lede":"AI-gile праве брадати чудак са AuDHD-ом и неколико битака за ментално здравље и много стрпљивих агената. За сада је приватан, у затвореној алфи са пријатељима. Хоћеш да пробаш кад се отвори?","join.btn":"Пријави интересовање","join.small":"Послаћемо ти мејл, ништа друго","footer.tag":"AI-gile. Без трагача, без колачића, без кафе за стендап.","footer.licence":"Пословна лиценца","footer.status":"Статус","footer.privacy":"Шта чувамо","footer.thanks":"Позиви захваљујући ChilledChat-у","form.sending":"Шаље се…","form.failed":"Није успело: покушај поново касније.","form.offline":"Није могуће допрети до AI-gile: покушај поново касније.","form.keep":"Ово користимо само да ти одговоримо, а затим бришемо. Без трагача, без колачића.","form.keepLink":"Шта чувамо","interest.title":"AI-gile: јави ми кад се алфа отвори","interest.description":"Остави мејл да чујеш кад се отвори затворена алфа или бета AI-gile.","interest.h1":"🔔 Јави ми кад се отвори","interest.lede":"AI-gile је у затвореној пре-алфи. Остави мејл и јавићемо се једном, кад буде места за тебе.","interest.email":"Твој мејл","interest.which":"Који тест?","interest.alpha":"Затворена алфа: рано, грубо, пуно промена","interest.beta":"Бета: стабилнија, касније","interest.both":"Било која, шта прво дође","interest.submit":"Упиши ме на листу","interest.thanks":"Хвала! На листи си.","licence.title":"AI-gile: пословна лиценца","licence.description":"Користиш AI-gile у послу? Затражи бесплатну пословну лиценцу.","licence.h1":"📜 Пословна лиценца","licence.lede":"Користиш AI-gile на послу? Реци нам ко си и чиме се бавиш. Ако то чини нешто добро, лиценца је бесплатна.","licence.company":"Компанија","licence.website":"Веб-сајт","licence.what":"Чиме се бавиш","licence.how":"Како помаже свету","licence.email":"Мејл","licence.submit":"Пријави се","licence.thanks":"Хвала! Одговорићемо мејлом.","status.title":"AI-gile статус","status.h1":"AI-gile статус","status.quiet":"Све мирно","status.intro":"Да ли AI-gile ради управо сада? Ова страница на сваких 5 минута проверава сајт, дељење табли, позиве и преузимање.","status.up":"Ради (одговор за {ms} ms)","status.slow":"Нема одговора на последњу проверу, покушавам поново","status.down":"Не ради: нема одговора на последње две провере","status.svc.web":"Сајт","status.svc.web.offers":"Овај сајт: шта је AI-gile и формулар за интересовање","status.svc.boards":"Дељење табли","status.svc.boards.offers":"Јавне табле, поруке између пријатеља и позивнице","status.svc.calls":"Позиви","status.svc.calls.offers":"Глас, видео и дељење екрана у AI-gile","status.svc.download":"Преузимање","status.svc.download.offers":"Windows инсталер и линкови за позивнице","status.checking":"Проверавам…","status.offline":"Тренутно не могу да допрем до услуге статуса (покушавам поново)","status.updated":"ажурирано {ago}","status.justNow":"управо сад","status.min":"пре {n} мин","status.hours":"пре {n} ч","status.days":"пре {n} д","privacy.title":"AI-gile: шта чувамо","privacy.h1":"Шта чувамо","privacy.lede":"Укратко: само оно што нам пошаљеш, и то не задуго.","privacy.only":"Само оно што нам пошаљеш: оно што упишеш у формулар, на пример свој мејл. Ништа друго о теби.","privacy.sealed":"Запечаћено је тако да га наш сервер не може прочитати: у твом прегледачу пре него што крене (у старијем прегледачу у тренутку кад стигне). Може да га отвори само наша табла.","privacy.server":"Брише се са сервера чим стигне на нашу таблу. Све што је тамо остало и после 30 дана свакако се брише.","privacy.board":"На нашој табли га чувамо само док ти не одговоримо, а онда га и тамо бришемо.","privacy.none":"Без трагача, без колачића, без аналитике.","privacy.local":"Твој језик и избор светле или тамне теме остају у твом прегледачу. Никад нам се не шаљу.","privacy.ask":"Желиш да нестане раније? Одговори на наш мејл и реци нам.","live.h2":"Гледајте како се гради, уживо","live.caption":"Свака картица је скривена: видите облик посла, а не речи.","live.watching.one":"уживо: {n} гледа","live.watching.other":"уживо: {n} гледа","live.last.now":"Последња картица је премештена управо сада","live.last.min.one":"Последња картица је премештена пре {n} минут","live.last.min.other":"Последња картица је премештена пре {n} минута","live.last.hour.one":"Последња картица је премештена пре {n} сат","live.last.hour.other":"Последња картица је премештена пре {n} сати","live.last.day.one":"Последња картица је премештена пре {n} дан","live.last.day.other":"Последња картица је премештена пре {n} дана","live.offline":"Табла уживо мало одмара. Навратите ускоро.","live.cols":"Backlog|Треба урадити|У току|Тим проверава|Чека твој тест|За тим|Готово","pitch.words.few":"{n} речи","pitch.letters.few":"{n} слова","pitch.chars.few":"{n} знака","count.line.html.few":"{n} картице на табли управо сад","tl.cards.few":"{n} картице","live.last.min.few":"Последња картица је премештена пре {n} минута","live.last.hour.few":"Последња картица је премештена пре {n} сата","live.last.day.few":"Последња картица је премештена пре {n} дана","footer.models":"AI-gile покреће AI моделе за тебе. Оно што они кажу и ураде је њихово, зато провери пре него што поверујеш.","privacy.ai.h":"AI део","privacy.ai.models":"AI-gile је табла. Посао раде AI модели других компанија, као што су Claude, Codex и Gemini, на твојим налозима.","privacy.ai.check":"Оно што пишу и раде потиче од њих и може бити погрешно. Провери пре него што се ослониш на то или објавиш.","privacy.ai.files":"Они мењају фајлове и покрећу команде у фасциклама које повежеш. Направи резервну копију.","privacy.ai.send":"Оно што даш моделу иде компанији која га покреће, по њеним условима. Важе услови и цене сваког од њих.","privacy.ai.asis":"AI-gile је рана пробна верзија, дата онаква каква јесте."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Канбан, аутоматизован.","Агенти, организовани.","Идеје, изграђене."]},{"n":3,"texts":["Канбан за роботе.","Идеје постају функције.","Бесплатан канбан агената."]},{"n":5,"texts":["Канбан табла коју воде агенти.","Ти пишеш картице. Агенти граде.","Бесплатно, локално, тестирано, помало смешно."]},{"n":8,"texts":["Бесплатна канбан табла на којој раде AI агенти.","Напиши идеју. Агенти је граде. Ти прихваташ.","Agile за једног човека и много стрпљивих робота."]},{"n":13,"texts":["Канбан табла на твом рачунару на којој AI агенти узимају картице и граде.","Напиши идеју. Тим агената је гради. Тестер је проверава, а ти одлучујеш.","Бесплатно, без налога и трагача: једна табла, пар робота и ти као шеф."]},{"n":21,"texts":["AI-gile је канбан табла за рад са AI агентима који пишу код. Они узимају картице; ти их тестираш и прихваташ.","Сваки пројекат добија вођу и тим AI агената. Коментариши било коју картицу и тим се хвата посла.","Бесплатна, лична табла задатака која ради на твом рачунару. Радници су роботи. Онај који каже да је ти."]},{"n":34,"texts":["Идеје стављаш на таблу. Тим AI агената од њих прави функције које раде, тестира их и враћа ти их са корацима за пробу. Ништа се не рачуна као готово док ти то не кажеш.","AI-gile је кућна канбан табла коју је Рич направио уз пуно помоћи агената којима сада управља. Бесплатна је, ради на твом рачунару и дели се са пријатељима, не продаје се.","Замисли обичну канбан таблу, са колонама од Backlog-а до Готово, само што картице узимају AI агенти. Јављају напредак, питају кад западну и увек сачекају твој палац горе."]},{"n":55,"texts":["AI-gile је канбан табла на којој тим чине AI агенти. Сваки пројекат има вођу који планира посао и помоћнике који граде. Кад је функција спремна, AI тестер је проба и направи снимак екрана, а онда стиже у твоју гомилу. Прихвати је, или коментариши па је раде поново.","Почело је као начин једне особе да прати много AI сесија кодирања одједном, а израсло је у праву таблу. Ради на твом рачунару, не тражи налог и нема трагача. Бесплатна је за пријатеље и радознале. Такође је недовршена, па очекуј грубе ивице и по неко изненађење.","Ево поштене верзије. И даље мораш сам да имаш идеје, и даље мораш сам да провериш резултате. Све између ради AI-gile: држи картице у реду, буди правог агента кад оставиш коментар, показује тачно шта се променило и све то сабира у једну кратку гомилу за тебе, па нема лутања од апликације до апликације."]},{"n":89,"texts":["AI-gile је бесплатна канбан табла коју покрећеш на свом рачунару. Уместо људи, сваки пројекат има тим AI агената: вођу који твоје идеје претвара у картице и план, и помоћнике који узимају картице по приоритету. Кад је нешто направљено, AI тестер прати кораке за тест и показује ти шта је видео. Затим чека у једној гомили која се зове За тебе. Прихватиш га, или коментаришеш и тим покушава поново. Ништа никад не стигне до Готово без тебе.","Неке ствари које можда не очекујеш. Ноћна стража допуњује колону Треба урадити док ти спаваш, бирајући картице којима не треба твој одговор. Бројач токена показује колико су агенти потрошили данас и ове недеље, а No Token Mode им каже да престану да троше. Можеш да пишеш пријатељима, а приватне поруке су шифроване од краја до краја. Табла говори око 120 језика, међу њима холандски, фламански, гусарски и клингонски. Ништа од тога не кошта ни динар, а ни ко ти га не покушава продати.","AI-gile је мали, лични пројекат, а не компанија. Рич је хтео да води неколико AI пројеката кодирања без отварања сваке апликације да провери стање, па су он и агенти направили таблу за то, а онда су помоћу ње направили остатак ње саме. У затвореној је пре-алфи, што значи да ради, углавном, за шачицу пријатеља. Нема странице са ценама, билтена ни плана раста. Ако ти звучи корисно, можеш да затражиш да пробаш кад се мало више отвори."]},{"n":144,"texts":["AI-gile је канбан табла за једног човека и много AI агената. Ради на твом рачунару и потпуно је бесплатна. Додајеш пројекте, и сваки пројекат добија вођу и мали тим. Ћаскаш са вођом, помало као на Discordu, и описујеш идеју; вођа је претвара у картице и план, па чека да притиснеш Крени. Тим пролази кроз картице по приоритету, помоћу једноставног алата за командну линију направљеног за језичке моделе. Пре него што ти се нешто врати, AI тестер прати кораке у копији апликације и прилаже снимак екрана. Готов посао стиже у твоју гомилу са измењеним фајловима и разликом. Прихватиш га, или оставиш коментар па се тим пробуди и покуша поново. Само ти можеш да преместиш картицу у Готово.","Отприлике један дан са AI-gile. Увече оставиш пар коментара: ово дугме је на погрешном месту, она листа треба да буде сортирана, може ли тамни режим. Одеш на спавање. Агенти прочитају коментаре, направе измене, тестирају их и врате ти их. Ако се Треба урадити испразни, ноћна стража га допуни из бекклога картицама којима не треба твој одговор. Ујутру те чека једна кратка гомила: пар питања и неколико ствари за пробу, свака са корацима које може да прати и поспана особа и са снимком екрана како ради. Кликнеш, прихватиш добре и вратиш остале. Бројач токена показује колико је све то потрошило, а No Token Mode је ту за скромније недеље. Затим доручкујеш, а у томе агенти још не могу да помогну.","Прво, шта AI-gile није. Није стартап, није на продају и нико не скупља твоје податке. То је бесплатна табла која ради на твом рачунару, без налога, без трагача и без колачића. А шта јесте: једно уредно место да видиш све своје AI пројекте кодирања одједном, са тимом агената који раде картице и тобом који доносиш одлуке. Спаја сродне картице, поправља збркане наслове и пази колико код остаје сажет. Говори око 120 језика, од холандског и фламанског до гусарског и клингонског. Пријатељи могу да пишу једни другима, приватно и шифровано. Направили су га Рич и велики број стрпљивих агената, углавном користећи њега самог. У затвореној је пре-алфи, па је на местима груб. Ако звучи забавно, лепо питај и можда уђеш раније."]}],"quips":{"1":"Једна реч. Смело. Можда превише смело.","3":"Три речи. Већ поштеније од већине страница производа.","8":"Осам речи. И даље краће од стендапа.","21":"Дужине су, успут, story points. Наравно да јесу.","55":"Педесет пет речи. Две картице су завршене док си ово читао.","144":"То је она дуга. Не постоји 233. Агенти су отишли на спавање."}},"timeline":{"first-idea.name":"Прва идеја","first-idea.line":"Сасвим први разговор, пре него што је постојао иједан ред кода.","first-board.name":"Прва табла","first-board.line":"Табла која прати сопствену изградњу: картице, колоне, превлачење, пројекти.","team-roles.name":"Тим и улоге","team-roles.line":"Профили агената, шаблони тимова, простори и ко шта ради.","install.name":"Инсталација и издања","install.line":"Зип који пријатељ може да инсталира, самоажурирање, канали и повратак на старо.","usage-saver.name":"Штедња потрошње","usage-saver.line":"Мери колико коштају покретања, држи код сажетим, чува твоје ограничење.","friends.name":"Пријатељи и дељење","friends.line":"Приватне поруке, прикривени релеј, позивнице, улоге и дељени пројекти.","languages.name":"Језици","languages.line":"Сваки текст на екрану у језичком фајлу, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер прво проверава сваку предају и показује шта је видео.","website.name":"Веб-сајт","website.line":"aigile.lol, тизер и ова временска линија.","streaming.name":"Ћаскање и стриминг","streaming.line":"Discord, Twitch, OBS, стример режим, GIF-ови и емоџији.","no-ai.name":"Издање без AI","no-ai.line":"Табла за људе који кодирају без AI, и јавне табле.","night-watch.name":"Ноћна стража","night-watch.line":"Чувар и Scrum Master држе тимове на задатку док ти спаваш.","p-more.name":"Све остало","p-more.line":"Мање идеје које чекају на ред.","p-android.name":"Телефон и Android","p-android.line":"Допри до табле са телефона, а затим изворна Android апликација.","p-release.name":"Алфа и даље","p-release.line":"Затворена алфа, живи сајт, па бета.","p-languages.name":"Још језика","p-languages.line":"130 језика и режим урањања за оне који уче језик.","p-engines.name":"Још AI мотора","p-engines.line":"За сваког агента изабери Claude, Codex, Gemini, Copilot или Cursor.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаке ризика, капије за спајање, картице за инциденте и заштитне ограде.","p-self.name":"Брига о теби","p-self.line":"Режим уморног, подсетници за бригу о себи и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобална подешавања сервера, улоге и планирање раста.","p-livestream.name":"Додаци за стриминг","p-livestream.line":"Twitch ћаскање, прилагођени емоџији и јавни приказ уживо."},"words":{"button":"📖 Стручни изрази","h":"📖 Објашњене речи","intro":"Бесплатна обука једноставним језиком: свака реч на коју наиђеш од прве идеје до услуге на коју се људи ослањају, уз Agile, прављење, одржавање безбедним и рад са AI успут.","search":"Претражи реч…","none":"Ниједна реч се не поклапа.","close":"Затвори","count":{"one":"{count} реч","other":"{count} речи"},"groups":[{"id":"idea","name":"💡 Идеја и истраживање"},{"id":"plan","name":"🗺️ Планирање посла"},{"id":"agile","name":"🔁 Agile начини рада"},{"id":"build","name":"🛠️ Прављење"},{"id":"test","name":"🧪 Тестирање и квалитет"},{"id":"change","name":"🔀 Безбедне измене"},{"id":"run","name":"🛎️ Рад сервиса"},{"id":"sec","name":"🔒 Безбедност и приватност"},{"id":"ai","name":"🤖 Рад са AI"},{"id":"money","name":"💰 Новац и лиценце"}],"list":[{"id":"discovery","g":"idea","word":"Истраживање (Discovery)","text":"Рана фаза у којој откриваш који проблем вреди решавати и за кога, пре него што се ишта направи.","also":["истраживање","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Опис проблема","text":"Једна или две реченице које кажу ко има проблем, шта је и зашто је важно, да сви циљају у исто.","also":["опис проблема","дефиниција проблема","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Корисник","text":"Особа која користи оно што правиш. Њене потребе су разлог зашто се посао ради.","also":["корисник","корисника","корисници","корисницима","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Заинтересована страна","text":"Свако коме је стало како ће посао испасти или на кога он утиче, као они који га плаћају, користе или подржавају.","also":["заинтересована страна","заинтересоване стране","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Персона","text":"Измишљена, али реална особа која представља једну врсту корисника, да тим може да пита „да ли би Сему ово било лако?“","also":["персона","персоне","персону","персонама","persona","personas"]},{"id":"userresearch","g":"idea","word":"Истраживање корисника","text":"Разговор са стварним људима и посматрање како раде, да би се сазнало шта им треба, уместо нагађања.","also":["истраживање корисника","интервјуи са корисницима","user research","user interviews"]},{"id":"journey","g":"idea","word":"Пут корисника","text":"Кораци које особа прави да би нешто урадила, од првог сазнања до краја, и ван твог производа. Кад то нацрташ, види се где запиње.","also":["пут корисника","путовање корисника","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Болна тачка (pain point)","text":"Нешто што људе данас нервира или успорава. Добри производи уклањају болне тачке.","also":["болна тачка","болне тачке","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Претпоставка","text":"Нешто у шта верујеш, али још није проверено. Кад запишеш претпоставке, види се шта прво треба проверити.","also":["претпоставка","претпоставке","претпоставци","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Хипотеза","text":"Најбоља претпоставка коју планираш да провериш, са оним што очекујеш да се деси, као „људи ће се пријавити ако је први месец бесплатан“.","also":["хипотеза","хипотезе","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Експеримент","text":"Мали планирани тест да сазнаш да ли идеја функционише, пре него што много уложиш у њу.","also":["експеримент","експеримента","експерименти","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Доказ концепта (PoC)","text":"Брз, груб покушај да се види може ли идеја уопште да ради. Обично се баци чим добијеш одговор.","also":["PoC","доказ концепта","proof of concept"]},{"id":"prototype","g":"idea","word":"Прототип","text":"Рани модел производа, често слике по којима се може кликати, да идеју испробаш на људима пре него што је направиш као што треба.","also":["прототип","прототипа","прототипи","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Једноставна скица екрана која показује шта где стоји, без боја и правог садржаја.","also":["wireframes","жичани модел","скица екрана"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Детаљна слика како ће екран изгледати, са правим бојама и текстом, али још ништа не ради.","also":["mockups","mock-up","mock-ups","макета","макете"]},{"id":"bizcase","g":"idea","word":"Пословно образложење (business case)","text":"Разлози за пројекат: колико кошта, шта доноси или штеди и који су ризици.","also":["пословно образложење","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Изводљивост","text":"Да ли се нешто заиста може направити и одржавати са временом, новцем и вештинама које имаш.","also":["изводљивост","изводљиво","feasibility"]},{"id":"outcome","g":"idea","word":"Ефекат (outcome)","text":"Промена коју желиш за људе, као мање пропуштених термина. Важнија је од тога колико се направи.","also":["ефекат","ефекти","исход","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Резултат рада (output)","text":"Нешто што тим направи, као нови екран или извештај. То што је направљено не значи аутоматски да некоме помаже.","also":["резултат рада","резултати рада","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Мерило успеха","text":"Број који показује да ли је посао урадио оно чему је служио, као више људи који заврше поруџбину.","also":["мерило успеха","мерила успеха","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Кључни показатељ учинка (KPI)","text":"Важан број који пратиш да видиш да ли све иде добро, као број пријава недељно.","also":["KPI","KPIs","кључни показатељ учинка","key performance indicator"]},{"id":"okr","g":"idea","word":"Циљеви и кључни резултати (OKR)","text":"Начин постављања циљева: циљ каже шта желиш, а неколико кључних резултата су бројеви који показују да је циљ постигнут.","also":["OKR","OKRs","циљеви и кључни резултати"]},{"id":"product","g":"plan","word":"Производ","text":"Оно што се прави и одржава за кориснике, као апликација, сајт или алат.","also":["производ","производа","производу","производи","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Визија производа","text":"Кратка изјава коме производ помаже и куда иде на дуге стазе.","also":["визија производа","визија","vision statement","product vision"]},{"id":"po","g":"plan","word":"Власник производа (PO)","text":"Особа која одлучује шта се прави и којим редом, да тим увек ради на ономе што је најважније. У AI-gile то си ти.","also":["PO","власник производа","product owner","product owners"]},{"id":"pm","g":"plan","word":"Менаџер производа (PM)","text":"Особа која води рачуна о правцу производа: које проблеме решава, за кога и зашто. PM може значити и менаџер пројекта, па провери на шта се мисли.","also":["PM","менаџер производа","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Менаџер пројекта","text":"Особа која пројекат држи у року и буџету, и прати ко шта ради и до када.","also":["менаџер пројекта","руководилац пројекта","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Мапа пута (roadmap)","text":"Груб план шта долази у наредним месецима, редом. Показује правац, не тачне датуме, и мења се како учиш.","also":["мапа пута","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Прекретница (milestone)","text":"Тачка у пројекту вредна обележавања, као „прва верзија уживо“ или „100 корисника“.","also":["прекретница","прекретнице","прекретници","прекретницама","кључна тачка","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Минимални употребљив производ (MVP)","text":"Најмања верзија производа која је и даље корисна стварним људима, да од њих рано учиш.","also":["MVP","MVPs","минимални употребљив производ","minimum viable product"]},{"id":"requirement","g":"plan","word":"Захтев","text":"Нешто што готов производ мора да ради или да буде.","also":["захтев","захтева","захтеви","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Обим посла (scope)","text":"Шта је укључено у посао и, подједнако важно, шта није.","also":["обим","обим посла","у обиму","ван обима","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Ширење обима (scope creep)","text":"Кад се послу постепено додаје све више тога, а нико се није договорио о додатном времену или трошку, па никад не буде готов.","also":["ширење обима","scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Функција (feature)","text":"Једна ствар коју производ може да уради за људе, као „ресетуј лозинку“.","also":["функција","функције","функционалност","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Велики комад посла, превелик да се уради одједном, па се дели на мање картице.","also":["epics","епик","епици"]},{"id":"story","g":"plan","word":"Корисничка прича (user story)","text":"Мали комад посла написан из угла корисника: „Као купац, желим да сачувам корпу, да куповину завршим касније.“ Покреће разговор о томе шта да се направи.","also":["корисничка прича","корисничке приче","user story","user stories"]},{"id":"ac","g":"plan","word":"Критеријуми прихватања (AC)","text":"Провере које картица мора да прође да би се рачунала као готова, договорене пре почетка посла, као „корпа је и даље ту кад се одјавим и поново пријавим“.","also":["AC","критеријуми прихватања","acceptance criteria"]},{"id":"task","g":"plan","word":"Задатак","text":"Један посао који треба урадити, често мали корак веће приче.","also":["задатак","задатка","задаци","задатака","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Тикет","text":"Друга реч за картицу: један комад посла или један захтев, праћен од почетка до краја.","also":["тикет","тикета","тикети","ticket","tickets"]},{"id":"priority","g":"plan","word":"Приоритет","text":"Колико је нешто важно или хитно у поређењу са свим осталим, да најважнији посао иде први.","also":["приоритет","приоритета","приоритети","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Одређивање приоритета","text":"Стављање посла по реду важности. Уобичајен начин је MoSCoW: Must have (мора), Should have (требало би), Could have (могло би), Won’t have this time (овог пута не).","also":["одређивање приоритета","приоритизација","MoSCoW"]},{"id":"estimate","g":"plan","word":"Процена","text":"Најбоља претпоставка колико је неки посао велики или колико ће трајати. То је претпоставка, а не обећање.","also":["процена","процене","проценама","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Начин да се величина посла процени међусобним упоређивањем картица („отприлике дупло веће од оне“), а не у сатима. Нису за поређење тимова.","also":["story point","поени приче","поен приче"]},{"id":"tshirt","g":"plan","word":"Величине мајица (T-shirt sizing)","text":"Процена величине посла као S, M, L или XL. Брза и довољно добра за рано планирање.","also":["величине мајица","t-shirt sizes","t-shirt sizing"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Игра за процењивање: сви истовремено показују картицу са величином, па они са највишом и најнижом проценом објасне зашто.","also":["Scrum poker","покер планирања"]},{"id":"dependency","g":"plan","word":"Зависност","text":"Кад један посао не може да почне или да се заврши док се не уради други.","also":["зависност","зависности","зависностима","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Блокада","text":"Све што тренутно спречава да посао иде напред, као одговор који недостаје или покварен алат.","also":["блокада","блокаде","блокер","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Рок","text":"Датум до кога нешто мора бити завршено.","also":["рок","рока","рокови","рокова","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Испорука (deliverable)","text":"Нешто конкретно што посао створи и преда, као страница која ради или извештај.","also":["испорука","испоруке","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Прогноза","text":"Предвиђање шта ће се вероватно десити, као када ће посао бити готов, на основу онога што знаш до сада.","also":["прогноза","прогнозе","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Метрика","text":"Све што меришеш и пратиш кроз време, као посете страници или колико траје поправка.","also":["метрика","метрике","метрици","metric","metrics"]},{"id":"feedback","g":"plan","word":"Повратна информација (feedback)","text":"Оно што ти људи кажу о твом раду, добро и лоше. Добијати га рано и често је срж Agile-а.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Листа чекања идеја и посла који још нису планирани, са најважнијим на врху. Ништа од тога се не ради док се не премести у „Треба урадити“."},{"id":"sprint","g":"agile","word":"Спринт","text":"Кратак, утврђен период рада (често недеља или две, никад више од месец дана) са циљем и договореним скупом картица које треба завршити.","also":["спринт","спринта","спринту","спринтом","спринтови","спринтова","sprint","sprints"]},{"id":"standup","g":"agile","word":"Стендап","text":"Кратка дневна провера: шта је ко из тима урадио, шта ради следеће и шта га омета. У Scrum-у се зове дневни scrum.","also":["стендап","стендапа","стендапу","стендапови","стендапова","standup","stand-ups","daily scrum","daily stand-up","дневни scrum"]},{"id":"kanban","g":"agile","word":"Канбан","text":"Начин рада у коме се картице крећу кроз колоне табле (као Треба урадити, У току, Готово), а тим ограничава колико је одједном у току, да посао стално тече."},{"id":"wip","g":"agile","word":"WIP лимит","text":"WIP је скраћеница за work in progress, то јест посао у току. WIP лимит је највећи број картица које једна колона треба да држи одједном, да тим завршава ствари пре него што започне нове.","also":["WIP","wip лимит","лимит"]},{"id":"dod","g":"agile","word":"Дефиниција Завршено","text":"Кратка листа тима шта значи „завршено“, на пример тестирано и објашњено, пре него што ти картица стигне. Њен близанац, Дефиниција Спремно за почетак, каже кад је картица довољно јасна да се почне.","also":["Definition of Ready","DoD","DoR","дефиниција спремности"]},{"id":"retro","g":"agile","word":"Ретро","text":"Редован осврт на то како тим ради, да се договоре једна или две ствари које ће следећи пут радити боље. Скраћено од ретроспектива. У AI-gile ретро предлаже измену начина рада тима, а ти кажеш Go или Још не.","also":["retro","ретроспектива","ретроспективе"]},{"id":"swarm","g":"agile","word":"Рој","text":"Сви у акцију: многи остављају други посао да би заједно решили једну хитну ствар док се не среди. У AI-gile сваки тим помаже на једном пројекту, а остали пројекти за то време чекају.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"У Scrum-у, особа која помаже тиму да добро ради: уклања оно што га блокира, пази да састанци не скрећу с теме и подучава добре навике, без командовања. У AI-gile Lead Scrum Master уочава заглављене картице, подстиче тимове и подсећа те на оно што чека, у свим пројектима.","also":["Lead Scrum Master","Скрам мастер"]},{"id":"agile","g":"agile","word":"Agile","text":"Начин рада у малим корацима: направиш мало, често показујеш праве резултате, учиш из онога што људи кажу и мењаш план успут, уместо да све планираш унапред.","also":["Agile development","agile ways of working","аџајл","agile"]},{"id":"manifesto","g":"agile","word":"Agile манифест","text":"Кратка изјава коју су 2001. написали људи који праве софтвер. Људе, радне резултате, блиску сарадњу са корисницима и прилагођавање променама ставља испред тешких планова и папирологије.","also":["Agile Manifesto","Manifesto for Agile Software Development","agile манифест"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Старији начин рада: испланираш све, па све направиш, па све тестираш, једна фаза за другом. Касне промене су тешке и скупе.","also":["waterfall model","водопад","модел водопада"]},{"id":"iteration","g":"agile","word":"Итерација","text":"Један круг прављења нечега, провере и побољшања. Agile рад је низ таквих кругова, а спринт је једна њихова врста.","also":["итерација","итерације","итерацији","iteration","iterations"]},{"id":"increment","g":"agile","word":"Инкремент","text":"Нови комад који ради, додат производу у спринту или кругу рада, и који се уклапа у оно што је већ било ту.","also":["инкремент","инкремента","инкременти","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Популаран Agile начин рада: мали тим ради у кратким спринтовима ка циљу, са утврђеним улогама и неколико редовних састанака за планирање, проверу и побољшање."},{"id":"scrumteam","g":"agile","word":"Scrum тим","text":"Мала група која ради посао у Scrum-у: власник производа, Scrum Master и програмери.","also":["Scrum тим","Scrum тимови","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum догађаји","text":"Редовни састанци у Scrum-у: планирање спринта, дневни scrum, преглед спринта и ретро. Многи их зову церемонијама.","also":["Scrum догађаји","церемоније","ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Планирање спринта","text":"Састанак на почетку спринта на коме се тим договара зашто је спринт важан, које картице узима и како да почне.","also":["планирање спринта","састанак за планирање","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Циљ спринта","text":"Једна реченица која каже чему спринт служи. Мањи задаци могу да се промене успут, све док је циљ постигнут.","also":["циљ спринта","циљеви спринта","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Картице изабране за текући спринт, са планом тима како да их уради.","also":["sprint backlogs","backlog спринта"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Цела уређена листа свега што би могло да се направи за производ, са најважнијим на врху. Стално се мења како учиш.","also":["product backlogs","backlog производа"]},{"id":"productgoal","g":"agile","word":"Циљ производа","text":"Већи резултат ка коме производ иде, који тиму помаже да бира шта ће радити следеће.","also":["циљ производа","циљеви производа","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Дорада backlog-а","text":"Редовно прегледање backlog-а да се картице среде, поделе, поређају и добију више детаља, па буду спремне за узимање. Зове се и backlog grooming.","also":["дорада backlog-а","backlog grooming","refinement","backlog refinement","grooming"]},{"id":"sprintreview","g":"agile","word":"Преглед спринта","text":"Састанак на крају спринта на коме тим показује шта је завршио и чује шта људи мисле, да би одлучио шта следи.","also":["преглед спринта","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Демо","text":"Показивање готовог посла на делу, уживо, људима који су га тражили.","also":["демо","демоа","демои","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Одређена количина времена за нешто. Кад истекне, станеш, чак и ако није све готово.","also":["timeboxed","timeboxes","временски оквир"]},{"id":"velocity","g":"agile","word":"Брзина (velocity)","text":"Колико посла тим обично заврши у спринту, да би се планирало колико да узме следећи пут. Није оцена колико се људи труде.","also":["брзина тима","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Капацитет","text":"Колико посла тим може да преузме у неком периоду, пошто се одбију одмори и други послови.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown дијаграм","text":"Дијаграм посла који је остао у спринту и опада из дана у дан. Ако линија остане равна, нешто је запело.","also":["burndown","burn-down chart","burndown chart","burndown графикон"]},{"id":"burnup","g":"agile","word":"Burnup дијаграм","text":"Дијаграм завршеног посла који расте кроз време, поред укупно планираног, да видиш када ћеш стићи.","also":["burnup","burn-up chart","burnup chart","burnup графикон"]},{"id":"kanbanboard","g":"agile","word":"Канбан табла","text":"Сама табла: колона за сваку фазу посла, са картицама које се крећу кроз њу.","also":["канбан табла","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull систем","text":"Начин рада у коме нови посао почиње тек кад неко има места да га узме, уместо да се гура некоме ко је већ претрпан.","also":["pull систем","систем повлачења","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Проток (flow)","text":"Колико глатко посао иде кроз таблу. Добар проток значи да се картице стално крећу и не гомилају.","also":["проток","проток посла","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Колико прође од тренутка кад неко нешто затражи до тренутка кад је готово.","also":["lead times","време испоруке"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Колико картици треба од тренутка кад рад на њој заиста почне до тренутка кад се заврши.","also":["cycle times","време циклуса"]},{"id":"throughput","g":"agile","word":"Пропусност (throughput)","text":"Колико се картица заврши за недељу дана, или у било ком одређеном времену.","also":["пропусност","throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Уско грло","text":"Једна фаза у којој се посао гомила и успорава све иза ње, као уски врат боце.","also":["уско грло","уска грла","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Ред преко табле који групише картице једне врсте, као хитан посао или картице једног тима.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Начин рада који уклања отпад (све што не помаже кориснику) и одржава проток посла."},{"id":"waste","g":"agile","word":"Отпад (waste)","text":"У Lean-у, све што захтева труд, а не помаже кориснику, као чекање, прерада или прављење ствари које нико не користи.","noTip":1},{"id":"kaizen","g":"agile","word":"Континуирано побољшање","text":"Стално мало напредовање кроз мале редовне промене, уз проверу да ли су помогле. Ретро састанци су један начин за то. Зове се и kaizen (кајзен).","also":["континуирано побољшање","kaizen","кајзен","continuous improvement"]},{"id":"selforg","g":"agile","word":"Самоорганизован тим","text":"Тим који сам одлучује како ће да уради посао, уместо да му се говори корак по корак.","also":["самоорганизован тим","самоорганизовање","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Мултифункционални тим","text":"Тим који има све вештине потребне да сам заврши посао, као дизајн, прављење и тестирање.","also":["мултифункционални тим","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Кратко истраживање ограничено временом, да се одговори на питање пре него што се крене у прави посао.","also":["spikes"]},{"id":"rework","g":"agile","word":"Прерада","text":"Поновно рађење посла јер први пут није урађен како треба.","also":["прерада","прераде","rework","reworked"]},{"id":"safe","g":"agile","word":"Agile у великом (SAFe)","text":"Начини да се Agile користи у више тимова у великој организацији. SAFe (Scaled Agile Framework) је један познат пример.","also":["agile у великом","scaled Agile"]},{"id":"repo","g":"build","word":"Репозиторијум","text":"Пројектни фолдер са кодом и његовом пуном историјом комитова. Може бити на твом рачунару, на GitHub-у или на оба места.","also":["репозиторијум","репо","репоа","repo","repository"]},{"id":"branch","g":"build","word":"Грана","text":"Посебна линија рада у коду, да се измене могу радити а да се не дира главна верзија.","also":["грана","гране","грани","грану","бранч","branch","branches"]},{"id":"commit","g":"build","word":"Комит","text":"Сачуван снимак кода са кратком белешком шта је промењено. Увек можеш да се вратиш на неки.","also":["комит","комита","комити","комитова","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Слање твојих сачуваних снимака (комитова) са овог рачунара на заједничку копију на мрежи, као GitHub, да буду сачувани и да их други могу добити."},{"id":"merge","g":"build","word":"Спајање","text":"Спајање измена из једне гране у другу, обично назад у главну верзију."},{"id":"pr","g":"build","word":"Pull request","text":"Захтев да се измене једне гране провере и споје у главну верзију. Неки сајтови то зову merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Рефакторисање","text":"Сређивање кода без промене онога што ради: мањи фајлови, јаснији називи, мање понављања."},{"id":"bug","g":"build","word":"Баг","text":"Нешто што не ради како треба.","also":["баг","бага","багу","багови","багова","bug","bugs"]},{"id":"peerreview","g":"build","word":"Преглед колега","text":"Други пар очију: неко други осим аутора проверава рад пре него што стигне до тебе, да мање грешака прође. У AI-gile други AI проверава сваку картицу.","also":["peer review","преглед кода","code review"]},{"id":"code","g":"build","word":"Код","text":"Написана упутства која рачунару кажу шта да ради. Зове се и изворни код.","also":["код","кода","коду","изворни код","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Програмски језик","text":"Језик за писање кода, као JavaScript, Python или Java. Различити одговарају различитим пословима.","also":["програмски језик","програмски језици","programming language","programming languages"]},{"id":"developer","g":"build","word":"Програмер (dev)","text":"Неко ко пише и мења код. Зове се и програмер или софтверски инжењер.","also":["програмер","програмера","програмери","девелопер","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Софтвер","text":"Програми који раде на рачунарима и телефонима, за разлику од самих машина (хардвера).","noTip":1},{"id":"app","g":"build","word":"Апликација (app)","text":"Скраћено од апликација: програм који људи користе да би нешто урадили, на телефону, рачунару или у веб прегледачу.","also":["апликација","апликације","апликацији","апликацију","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Веб апликација","text":"Апликација која ради у веб прегледачу, па ништа није потребно инсталирати.","also":["веб апликација","веб апликације","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Део апликације који видиш и на који кликћеш: екрани, дугмад и речи, често у твом прегледачу.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Део апликације иза сцене који чува податке и ради посао кад на нешто кликнеш, као провера твоје лозинке.","also":["back-end","backend","позадински део"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Рад и на предњем и на позадинском делу.","also":["full-stack"]},{"id":"ui","g":"build","word":"Кориснички интерфејс (UI)","text":"Оно што особа види и користи на екрану: распоред, дугмад, менији и текст.","also":["UI","кориснички интерфејс","user interface"]},{"id":"ux","g":"build","word":"Корисничко искуство (UX)","text":"Какав је осећај кад нешто користиш: лако, јасно и пријатно, или збуњујуће и споро.","also":["UX","корисничко искуство","user experience"]},{"id":"accessibility","g":"build","word":"Приступачност (a11y)","text":"Да ствари могу да користе сви, укључујући људе који слабо виде, не могу да користе миш или користе читач екрана.","also":["a11y","приступачност","accessibility"]},{"id":"responsive","g":"build","word":"Респонзиван дизајн","text":"Прављење страница тако да се уклопе и добро раде на екрану било које величине, од телефона до великог монитора.","also":["респонзиван дизајн","прилагодљив дизајн","responsive design"]},{"id":"designsys","g":"build","word":"Дизајн систем","text":"Заједнички комплет боја, фонтова, дугмади и правила, да сваки екран изгледа и понаша се на исти начин.","also":["дизајн систем","дизајн системи","design system","design systems"]},{"id":"architecture","g":"build","word":"Архитектура","text":"Општи облик система: које су главне целине и како разговарају једна с другом."},{"id":"database","g":"build","word":"База података (DB)","text":"Уређено складиште информација, као веома моћна табела коју апликација може да чита и мења.","also":["база података","базе података","бази података","database","databases","DB"]},{"id":"schema","g":"build","word":"Шема базе података","text":"Распоред базе података: које табеле информација има и шта иде у сваку.","also":["шема","шема базе података","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Скраћено од структурирани упитни језик: језик којим се од многих база података траже информације или се у њима мењају.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Подаци","text":"Информације које рачунар чува, као имена, поруџбине или подешавања.","also":["подаци","података","подацима","data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Сервер","text":"Рачунар који је стално укључен и одговара на захтеве других рачунара, као слање веб странице кад је посетиш.","also":["сервер","сервера","сервери","серверу","server","servers"]},{"id":"client","g":"build","word":"Клијент","text":"Страна која нешто тражи, обично твој прегледач или апликација, у разговору са сервером. У послу то значи и једноставно муштерија.","also":["клијент","клијента","клијенти","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Скраћено од интерфејс за програмирање апликација: фиксни мени захтева које један програм може да упути другом, као питање метеоролошкој служби за данашњу прогнозу.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Једна ставка на менију API-ја: веб адреса коју програм може да позове да нешто добије или пошаље.","also":["endpoints","крајња тачка"]},{"id":"integration","g":"build","word":"Интеграција","text":"Повезивање два система да раде заједно, као твоја продавница која шаље поруџбине твом програму за рачуноводство.","also":["интеграција","интеграције","интеграцији","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Порука коју један систем сам шаље другом у тренутку кад се нешто деси, као „уплата примљена“.","also":["webhooks"]},{"id":"library","g":"build","word":"Библиотека","text":"Готов код који је неко други написао и који можеш поново да користиш уместо да га пишеш од нуле.","also":["библиотека","библиотеке","библиотеци","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Готова структура за прављење апликације која одређује већину тога како је код распоређен, као носећа конструкција куће коју попуњаваш.","also":["frameworks","радни оквир"]},{"id":"sdk","g":"build","word":"Комплет за развој софтвера (SDK)","text":"Кутија са алатима, кодом и примерима за прављење софтвера за једну платформу или услугу.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Софтверска зависност","text":"Библиотека или алат који је твом коду потребан да би радио. Важно је одржавати их ажурним ради безбедности.","also":["софтверска зависност","софтверске зависности","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Пакет","text":"Скуп готовог кода који можеш да инсталираш и користиш у пројекту.","also":["пакет","пакета","пакети","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Менаџер пакета","text":"Алат који преузима и ажурира пакете од којих твој код зависи. npm је уобичајен.","also":["менаџер пакета","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Најраспрострањенији алат за чување историје измена кода, у облику комитова и грана."},{"id":"github","g":"build","word":"GitHub","text":"Сајт који држи Git репозиторијуме на мрежи, да тимови деле код, прегледају измене и прате посао."},{"id":"vcs","g":"build","word":"Контрола верзија","text":"Чување потпуне историје сваке измене фајлова, да видиш ко је шта променио и да се вратиш уназад ако затреба. Git то ради.","also":["контрола верзија","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Прављење сопствене пуне копије репозиторијума, са његовом историјом, на твом рачунару.","also":["cloned","cloning","клонирање","клонирати"]},{"id":"pull","g":"build","word":"Pull","text":"Преузимање најновијих комитова са заједничке копије (као GitHub) на твој рачунар. Супротно од push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Главна грана","text":"Званична верзија кода од које сви раде, која се често зове main или master.","also":["главна грана","main branch","master branch"]},{"id":"conflict","g":"build","word":"Конфликт при спајању (merge conflict)","text":"Кад две измене дирају исте редове на различите начине, па рачунар не може да их споји и човек мора да бира.","also":["конфликт при спајању","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Приказ који тачно показује шта се променило између две верзије: додати редови и уклоњени редови.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Твоја копија туђег репозиторијума, коју можеш да мењаш а да не дираш њихов.","also":["forks","forked"]},{"id":"script","g":"build","word":"Скрипта","text":"Кратак програм који сам ради један посао, као сређивање фајлова или покретање апликације.","also":["скрипта","скрипте","скрипти","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Претварање кода у нешто спремно за покретање, или сам резултат спреман за покретање.","also":["builds","билд","билдови"],"noTip":1},{"id":"compile","g":"build","word":"Компајлирање","text":"Превођење кода који су написали људи у облик који рачунар може директно да изврши.","also":["компајлирање","компајлер","компајлирати","compile","compiler"]},{"id":"cli","g":"build","word":"Командна линија (CLI)","text":"Текстуални прозор у који куцаш упутства за рачунар уместо да кликћеш. Зове се и терминал.","also":["командна линија","терминал","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Конфигурација (config)","text":"Подешавања која одређују како се софтвер понаша, а држе се одвојено од кода да би се лако мењала.","also":["конфигурација","конфигурације","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Променљива окружења","text":"Подешавање које се програму преда кад се покрене, често за адресе или лозинке да се не уписују у код.","also":["променљива окружења","променљиве окружења","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Тражење узрока зашто нешто не ради, и његово отклањање.","also":["debug","debugged","дебаговање","дебагирање"]},{"id":"pairing","g":"build","word":"Програмирање у пару","text":"Две особе (или човек и AI) раде заједно на истом коду: једна куца, друга проверава.","also":["програмирање у пару","pair programming","pairing"]},{"id":"docs","g":"build","word":"Документација (docs)","text":"Написана објашњења како нешто ради или како се користи.","also":["документација","документације","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Први фајл који треба прочитати у репозиторијуму: шта је пројекат и како да се покрене.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Наслеђени систем (legacy)","text":"Старији систем који се још користи и тешко се мења, често зато што га мало људи још разуме.","also":["наслеђени систем","наслеђени системи","легаси","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Технички дуг","text":"Пречице које сада штеде време, а касније измене чине споријим, као зајам на који расте камата. Рефакторисање га отплаћује.","also":["технички дуг","техничког дуга","technical debt","tech debt"]},{"id":"test","g":"test","word":"Тест","text":"Провера да нешто ради како треба. Неке тестове рачунар сам покреће сваки пут кад се код промени; у другима ти испробаваш готову картицу пре него што је прихватиш.","also":["тест","теста","тестови","тестова","тестирање","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Скраћено од обезбеђење квалитета: све што се ради да би се осигурало да је посао исправан пре него што оде уживо. У AI-gile то значи аутоматске провере: кад је QA црвен, нешто није прошло и не може да оде уживо док се то не поправи.","also":["провера квалитета","провере квалитета","обезбеђење квалитета"]},{"id":"testpile","g":"test","word":"Гомила за тестове","text":"Завршене картице које чекају да их испробаш, једна за другом. Прихвати једну или је врати са белешком, и стиже следећа.","also":["гомиле за тестове"]},{"id":"autotest","g":"test","word":"Аутоматски тест","text":"Провера коју рачунар сам ради сваки пут кад се код промени, да се грешке рано ухвате.","also":["аутоматски тест","аутоматски тестови","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ручни тест","text":"Особа која ручно испробава урађено да види да ли ради како треба.","also":["ручни тест","ручни тестови","ручно тестирање","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Јединични тест (unit test)","text":"Мала аутоматска провера једног ситног комада кода, засебно.","also":["јединични тест","јединични тестови","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Интеграциони тест","text":"Провера да неколико делова исправно ради заједно, а не само један по један.","also":["интеграциони тест","интеграциони тестови","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Тест од почетка до краја (E2E)","text":"Тест који се понаша као прави корисник од почетка до краја, као пријава, куповина и плаћање.","also":["E2E","end-to-end test","end-to-end tests","E2E тест"]},{"id":"uat","g":"test","word":"Корисничко прихватно тестирање (UAT)","text":"Људи који су тражили тај посао сами га испробају и кажу да ли ради оно што им треба. Гомила за тестове у AI-gile-у је његова верзија тога.","also":["UAT","прихватно тестирање","acceptance testing"]},{"id":"regression","g":"test","word":"Регресија","text":"Нешто што је раније радило, а покварило се после измене. Регресиони тестови проверавају да старе ствари и даље раде.","also":["регресија","регресије","регресиони тест","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke тест","text":"Врло брза провера да главне ствари уопште раде, на пример одмах пошто измена оде уживо. Ако падне, стани и погледај.","also":["smoke тест","smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Истраживачко тестирање","text":"Слободно испробавање производа и чачкање по њему на различите начине, да се нађу проблеми које планиране провере не би ухватиле.","also":["истраживачко тестирање","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Тест случај","text":"Један написан сценарио за пробу: кораци и шта треба да се деси.","also":["тест случај","тест случајеви","test case","test cases"]},{"id":"coverage","g":"test","word":"Покривеност тестовима","text":"Колико кода проверавају аутоматски тестови. Више је обично безбедније, али висока покривеност сама не доказује да све добро ради.","also":["покривеност тестовима","покривеност кода","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Тест подаци","text":"Измишљене примерне информације које се користе при тестирању, да се не открију приватни подаци стварних људи.","also":["тест подаци","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Гранични случај (edge case)","text":"Необична ситуација на ивици, као празан формулар или име са апострофом, где се ствари често покваре.","also":["гранични случај","гранични случајеви","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Срећан пут (happy path)","text":"Нормалан пут на коме све иде како треба. Добро тестирање проба и несрећне путеве."},{"id":"perftest","g":"test","word":"Тестирање перформанси","text":"Провера колико је нешто брзо и како се носи под оптерећењем.","also":["тестирање перформанси","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Тестирање под оптерећењем","text":"Провера како се систем носи кад га много људи користи истовремено.","also":["тестирање под оптерећењем","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Безбедносно тестирање","text":"Тражење слабости које би некоме омогућиле да злоупотреби систем или види оно што не би смео.","also":["безбедносно тестирање","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Тестирање приступачности","text":"Провера да људи различитих способности могу да користе производ, укључујући читач екрана или само тастатуру.","also":["тестирање приступачности","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Аутоматска провера која уочава вероватне грешке и неуредан стил у коду, као провера правописа за програме.","also":["linter","lint","линтер"]},{"id":"static","g":"test","word":"Статичка анализа","text":"Аутоматска провера кода на проблеме читањем, без покретања.","also":["статичка анализа","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Нестабилан тест (flaky)","text":"Тест који некад прође а некад падне без јасног разлога, па му се не може потпуно веровати.","also":["нестабилан тест","нестабилни тестови","flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Репродукција (repro)","text":"Намерно поновно изазивање бага истим корацима, да се проучи и поправи. Записивање тих корака је најкориснији део извештаја о багу.","also":["репродукција","репро","repro","reproduce","steps to reproduce","кораци за репродукцију"]},{"id":"severity","g":"test","word":"Озбиљност (severity)","text":"Колико је лоша последица проблема, од ситне сметње до заустављања свега.","also":["озбиљност","ниво озбиљности","severity","severity level"]},{"id":"deploy","g":"change","word":"Деплој","text":"Копирање нове верзије софтвера на рачунаре који га покрећу, као тест копију или продукцију."},{"id":"release","g":"change","word":"Издање","text":"Именован пакет завршеног посла који иде уживо заједно, са кратким белешкама о томе шта се променило. 🚀 Издања пишу белешке из завршених картица.","also":["издања","release","релиз"]},{"id":"rollback","g":"change","word":"Враћање уназад","text":"Враћање на последњу верзију која је радила кад нова прави невоље. У AI-gile, „Врати уназад“ скупља кораке поништавања записане уз сваку измену у једну контролну листу.","also":["rollback","врати уназад","враћено уназад"]},{"id":"live","g":"change","word":"Уживо","text":"Права верзија коју људи користе, за разлику од копије за испробавање. Програмери је зову и продукција.","also":["продукција","live"],"noTip":1},{"id":"change","g":"change","word":"Измена","text":"Планирана измена нечега на шта се људи ослањају, прво записана: шта, зашто, ризик, када и како је поништити. Почни је са 🔀 Поднеси измену.","also":["измене","захтев за измену","захтеви за измену"],"noTip":1},{"id":"risk","g":"change","word":"Ризик","text":"Нешто што би могло да пође наопако, оцењено по томе колико је вероватно и колико би било лоше. ⚠️ Ризици их држе на једној листи, највећа оцена прва, сваки са датумом кад га поново погледати.","also":["ризици","регистар ризика"]},{"id":"chgwin","g":"change","word":"Прозор за измене","text":"Термини кад измене смеју да иду уживо, на пример миран уторак увече. Ван прозора картица измене не може да се заврши, осим ако је хитно.","also":["прозори за измене","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Последња провера непосредно пре него што измена оде уживо: сваки ко мора да одобри каже Go или No go. Наставља се само кад сви кажу Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрење","text":"Чекање на да пре него што посао почне. Картица коју поднесе пријатељ, или измена, чека у ✅ Одобрењима док је не одобриш или одбијеш.","also":["одобрења","одобри"]},{"id":"quiettime","g":"change","word":"Тихо време","text":"Период, као током стрима уживо, демоа или преко ноћи, када ништа не иде уживо. Тимови настављају да раде и тестирају, али излазак уживо чека док се не заврши. Другде се зове change freeze.","also":["тихи термини","замрзавање измена","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Начин рада у коме људи који праве софтвер и људи који га покрећу раде као један тим, уз пуно аутоматизације, да измене иду уживо често и безбедно."},{"id":"cicd","g":"change","word":"CI/CD (континуирана интеграција и испорука)","text":"Измене свих се често спајају у главну верзију и сваки пут аутоматски проверавају (континуирана интеграција), па је софтвер увек спреман да оде уживо притиском на дугме (континуирана испорука).","also":["CI/CD","CI","CD","континуирана интеграција","континуирана испорука","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Континуирано пуштање у рад","text":"Корак даље од континуиране испоруке: свака измена која прође провере иде уживо сама, без дугмета за притискање.","also":["континуирано пуштање у рад","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Аутоматски низ корака кроз које измена пролази на путу ка продукцији, као билд, тест, па деплој.","also":["pipelines","пајплајн"]},{"id":"environment","g":"change","word":"Окружење","text":"Једна одвојена копија система за једну намену, као једна за прављење, једна за тестирање и продукција.","also":["окружење","окружења","окружењу","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Развојно окружење","text":"Копија у којој програмер ради, често на сопственом рачунару, где никоме не шкоди ако се нешто поквари.","also":["развојно окружење","development environment","dev environment"]},{"id":"testenv","g":"change","word":"Тест окружење","text":"Одвојена копија система која се користи само за тестирање, да права услуга остане нетакнута.","also":["тест окружење","test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Последња копија подешена исто као продукција, за завршну проверу пре него што измена оде уживо.","also":["staging environment","стејџинг"]},{"id":"artifact","g":"change","word":"Артефакт билда (build artifact)","text":"Фајл или пакет који build производи, спреман да се сачува, провери или пусти уживо.","also":["артефакт билда","артефакт","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Хитна поправка која се брзо пушта уживо, мимо уобичајеног плана, зато што је нешто важно покварено.","also":["hotfixes","хитна поправка"]},{"id":"patch","g":"change","word":"Patch","text":"Мало ажурирање које поправља баг или затвара безбедносну рупу. Важно је брзо примењивати безбедносне закрпе.","also":["patches","security patch","security patches","закрпа","безбедносна закрпа"]},{"id":"version","g":"change","word":"Број верзије","text":"Ознака као 2.4.1 која каже коју верзију имаш. Често се први број мења за велике промене, а последњи за мале поправке.","also":["број верзије","бројеви верзија","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Напомене уз издање","text":"Кратка, једноставна листа онога што се променило у издању, за људе који га користе, укључујући поправке и позната ограничења. Зове се и changelog.","also":["напомене уз издање","release notes","changelog","change log","дневник измена"]},{"id":"flag","g":"change","word":"Feature flag","text":"Прекидач за укључивање и искључивање једне функције, да нови посао може да оде уживо скривен и да се укључи (или поново искључи) без новог издања.","also":["feature flags","feature toggle","feature toggles","прекидач функције"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Поправљање лошег издања брзим пуштањем нове, исправљене верзије уместо враћања на стару.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary издање","text":"Пуштање измене уживо прво за малу групу, а за све тек кад изгледа у реду. Име долази од канаринаца које су рудари носили под земљу као рано упозорење.","also":["canary издање","canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green пуштање у рад","text":"Држање две копије живог система и пребацивање људи на нову одједном, да можеш одмах да се вратиш ако нешто пође по злу.","also":["blue-green","blue green deployment","blue-green deployment","плаво-зелено пуштање"]},{"id":"zerodown","g":"change","word":"Пуштање у рад без прекида","text":"Пуштање нове верзије уживо а да услуга за кориснике никад не стане.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Управљање променама (change enablement)","text":"Помагање да измене успеју: мерење ризика, добијање правог одобрења и избор доброг времена. Зове се и change management.","also":["управљање променама","change enablement","change management"]},{"id":"cab","g":"change","word":"Савет за измене (CAB)","text":"Група која прегледа важне измене и договара да ли и када могу да се спроведу.","also":["CAB","савет за измене","change advisory board"]},{"id":"stdchange","g":"change","word":"Стандардна измена","text":"Измена мањег ризика која се сваки пут ради на исти проверен начин, па је унапред одобрена.","also":["стандардна измена","стандардне измене","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Нормална измена","text":"Измена која мора да се провери и одобри пре него што се спроведе.","also":["нормална измена","нормалне измене","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Ванредна измена","text":"Измена која мора одмах да се уради да се поправи или спречи озбиљна невоља, уз брже одобрење у складу с тим.","also":["ванредна измена","хитна измена","ванредне измене","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Аутоматизација","text":"Препуштање рачунару да сам ради посао који се понавља, па је брже и сваки пут урађено на исти начин.","also":["аутоматизација","аутоматизовано","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Инфраструктура","text":"Машине, мреже и услуге на којима софтвер ради.","also":["инфраструктура","инфраструктуре","infra"]},{"id":"iac","g":"change","word":"Инфраструктура као код (IaC)","text":"Опис сервера и подешавања у фајловима који се држе уз код, да се увек могу изнова изградити потпуно исто.","also":["IaC","инфраструктура као код","infrastructure as code"]},{"id":"cloud","g":"change","word":"Облак (cloud)","text":"Изнајмљивање рачунара, складишта и услуга од великог пружаоца преко интернета, уместо да машине поседујеш ти.","also":["облак","клауд","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Пружалац услуга у облаку","text":"Компанија која изнајмљује рачунарску снагу преко интернета, као Amazon Web Services (AWS), Microsoft Azure или Google Cloud.","also":["пружалац услуга у облаку","cloud провајдер","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Хостинг","text":"Место где твоја апликација или сајт живе и раде да би људи могли да их отворе, обично изнајмљено од неке компаније.","also":["хостинг","хостинга","hosting"]},{"id":"domain","g":"change","word":"Име домена","text":"Веб адреса коју људи куцају, као example.com. Изнајмљује се на годину дана, па га треба обнављати.","also":["име домена","домен","домена","domain","domain name","domain names"]},{"id":"dns","g":"change","word":"DNS","text":"Скраћено од систем имена домена: адресар интернета који име као example.com претвара у адресу правог рачунара.","also":["domain name system"]},{"id":"container","g":"change","word":"Контејнер","text":"Запечаћен пакет који држи апликацију и све што јој треба, да ради исто на сваком рачунару. Docker је најпознатији алат.","also":["контејнер","контејнера","контејнери","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Виртуелна машина (VM)","text":"Привидни рачунар који ради унутар правог, па једна велика машина може да се понаша као више њих.","also":["VM","VMs","виртуелна машина","виртуелне машине","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Покретање кода без бриге о било каквим серверима: пружалац га покреће кад треба, а ти плаћаш оно што користиш."},{"id":"lb","g":"change","word":"Балансер оптерећења (load balancer)","text":"Нешто што распоређује посетиоце на више сервера, да ниједан не буде преоптерећен.","also":["балансер оптерећења","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Практично складиште недавних резултата које се држи при руци, да се иста ствар не мора поново преузимати или рачунати. Брисање кеша може да поправи странице које изгледају застарело.","also":["caches","caching","cached","кеш","кеширање"]},{"id":"cdn","g":"change","word":"Мрежа за испоруку садржаја (CDN)","text":"Светска мрежа сервера која држи копије твојих страница и слика близу посетилаца, да се брзо учитавају.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Миграција","text":"Пребацивање података или система са старог окружења на ново, или пажљива измена распореда базе података.","also":["миграција","миграције","миграцији","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Услуга","text":"Нешто што си направио и на шта се људи ослањају, као сајт или апликација, о чему се води рачуна да стално ради. Означи „Овај пројекат је сервис“ и напиши шта нуди, ко га користи и ко дежура.","also":["услуге","услугу","сервис","сервиси"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Колико времена услуга ради, обично у процентима. 99,9% и даље дозвољава око 43 минута застоја месечно.","also":["uptime percentage","проценат доступности"]},{"id":"uptime","g":"run","word":"Провера доступности","text":"Аутоматска провера на сваких неколико минута да ли твој сервис још одговара. Ако не успе неколико пута заредом, AI-gile сам отвара картицу инцидента.","also":["uptime checks","провере доступности"]},{"id":"statuspage","g":"run","word":"Страница статуса","text":"Јавна страница која показује да ли сервис ради (зелено, наранџасто или црвено), са последњом вешћу, да би људи који га користе могли сами да провере уместо да питају.","also":["странице статуса","статусна страница","status page"]},{"id":"desk","g":"run","word":"Служба за подршку","text":"Место где стижу питања и пријаве од људи који користе твој сервис. AI-gile сваку разврста као захтев, инцидент или идеју и каже ти кад личи на нешто што је већ пријављено.","also":["службе за подршку","help desk","helpdesk","service desk","desk"]},{"id":"svcrequest","g":"run","word":"Захтев за услугу","text":"Кад неко тражи нешто уобичајено, као нови налог или мало помоћи, уместо да пријави да је нешто покварено. Чека свој ред; инцидент иде први.","also":["захтеви за услугу","захтев","захтеви"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нешто што је покварено или не ради како треба за људе који га користе управо сада, као сајт који не ради или је врло спор. 🔥 картица инцидента прескаче ред: враћање у рад долази прво.","also":["инциденти","испад"]},{"id":"major","g":"run","word":"Велики инцидент","text":"Велики инцидент: погођено је много људи, или су новац или подаци у опасности. Једно дугме ставља све тимове на њега (рој), буди онога ко дежура и тражи вест о статусу на сваких 30 минута.","also":["велики инциденти","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Бити онај ко се јавља кад се нешто поквари, чак и ноћу. Сваки сервис има дежурног члана тима кога први буде због његових инцидената.","also":["дежурни","дежура","on call","on-call"]},{"id":"replyby","g":"run","word":"Рок за одговор","text":"Колико картица сме да чека на први одговор, на пример сат времена за инцидент. После тога добија црвени сат, да се ништа не заборави у тишини. Зове се и циљно време одзива.","also":["рокови за одговор","циљно време одзива"]},{"id":"postmortem","g":"run","word":"Анализа после инцидента","text":"Кратак поглед уназад после инцидента: шта се десило, шта је помогло и шта променити, без окривљавања било кога. Инцидент не може да се затвори без ње. Често се зове и post-mortem.","also":["анализе после инцидента","post-mortem","постмортем"]},{"id":"problem","g":"run","word":"Проблем","text":"Скривени узрок иза једног или више инцидената. Картица 🧩 проблема спаја инциденте који се стално враћају, да се узрок нађе и поправи заувек.","also":["проблеми"],"noTip":1},{"id":"rootcause","g":"run","word":"Основни узрок","text":"Прави разлог зашто се нешто покварило, а не само оно што си видео да не ради. Поправи основни узрок и инцидент престаје да се враћа.","also":["основни узроци","root cause","корени узрок"]},{"id":"workaround","g":"run","word":"Заобилазно решење","text":"Начин да ствари раде док права поправка не буде спремна, на пример рестарт кад се нешто заглави. Записује се на картицу проблема да нико не мора поново да га смишља.","also":["заобилазна решења","workaround","привремено решење"]},{"id":"knownerror","g":"run","word":"Позната грешка","text":"Проблем чији је узрок схваћен, али још није поправљен, обично са записаним заобилазним решењем. Листа 🧩 Познате грешке их приказује, да сви користе заобилазно решење уместо да поново копају.","also":["познате грешке","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Упутство корак по корак за поправку познате врсте квара, да се сваки пут уради исто и брзо. После великог инцидента тим ти га може предложити да га одобриш.","also":["runbook-ови","ранбук","упутство за рад"]},{"id":"ci","g":"run","word":"Ставка конфигурације","text":"Једна ствар од које твој сервис зависи, као што су сервер, домен, сертификат, кључ или добављач. 🗂️ Ставке конфигурације их наводе по сервису, па видиш на шта инцидент утиче и шта треба обновити или резервно копирати.","also":["ставке конфигурације"]},{"id":"expiry","g":"run","word":"Датум истека","text":"Датум када нешто престаје да ради ако се не обнови, као безбедносни сертификат сајта или његова веб адреса. AI-gile прати ове датуме и прави једну картицу за обнову сваког од њих 30 дана унапред, да ништа не стане изненада.","also":["датуми истека","истек","праћење истека"]},{"id":"backup","g":"run","word":"Резервна копија","text":"Сачувана копија твојих података од раније, на коју можеш да се ослониш ако се нешто изгуби или оштети. AI-gile сваки дан прави резервну копију твојих табли.","also":["резервне копије","бекап","backup"]},{"id":"restore","g":"run","word":"Враћање података","text":"Враћање података из резервне копије. Резервна копија заиста вреди тек кад знаш да може да се врати, па вреди то повремено испробати.","also":["врати","враћено","restore","опоравак"]},{"id":"svcreview","g":"run","word":"Преглед сервиса","text":"Поглед уназад на један месец сервиса: отворени и поправљени инциденти, колико брзо су људи добили одговор, доступност и потрошени токени. Месечни преглед то приказује за сваки сервис.","also":["прегледи сервиса","месечни преглед","месечни прегледи"]},{"id":"accessreview","g":"run","word":"Преглед приступа","text":"Провера сваких 90 дана ко још може да уђе: линкови за дељење, улоге пријатеља и сачуване лозинке и кључеви. Сваки приступ задржиш или уклониш, да стари приступ не остане.","also":["прегледи приступа"]},{"id":"improvements","g":"run","word":"Листа побољшања","text":"Све у чему је тим одлучио да буде бољи, на једном месту: предлози са ретроа, радње из прегледа и поправке проблема, свака са својим статусом. Наћи ћеш је под 📈 Побољшања.","also":["листе побољшања","побољшања"]},{"id":"tokencap","g":"run","word":"Лимит токена","text":"Месечно ограничење токена које агенти сервиса смеју да потроше. На 80% добијаш упозорење; на 100% њихов рад у позадини чека до следећег месеца или док не повећаш лимит.","also":["лимити токена"]},{"id":"svcmgmt","g":"run","word":"Управљање услугама","text":"Све што је потребно да услуга остане корисна и да ради за људе који се на њу ослањају, из дана у дан.","also":["управљање услугама","управљање услугом","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Широко коришћен водич за добро управљање услугама, који покрива ствари као инциденте, проблеме и измене. Име је некад значило IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Управљање IT услугама (ITSM)","text":"Вођење технологије као услуге за људе, са јасним начинима за обраду захтева, инцидената, измена и побољшања.","also":["ITSM","управљање IT услугама","IT service management"]},{"id":"managed","g":"run","word":"Управљана услуга (managed service)","text":"Услуга коју неко други води и одржава за тебе, по договору колико добро мора да ради.","also":["управљана услуга","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Власник услуге","text":"Особа која одговара за услугу у целини: колико добро ради, колико кошта и како се побољшава.","also":["власник услуге","власници услуга","service owner","service owners"]},{"id":"sla","g":"run","word":"Споразум о нивоу услуге (SLA)","text":"Писано обећање корисницима колико добро ће услуга радити, као „доступна 99,9% времена“ или „одговор у року од сат времена“, често уз повраћај новца ако се прекрши.","also":["SLA","SLAs","споразум о нивоу услуге","service level agreement"]},{"id":"slo","g":"run","word":"Циљ нивоа услуге (SLO)","text":"Тимов сопствени циљ колико добро услуга треба да ради током неког периода, обично постављен мало строжије од SLA ради сигурности.","also":["SLO","SLOs","циљ нивоа услуге","service level objective"]},{"id":"sli","g":"run","word":"Показатељ нивоа услуге (SLI)","text":"Стварно мерење које упоређујеш са циљем, као удео посета које су се добро учитале.","also":["SLI","SLIs","показатељ нивоа услуге","service level indicator"]},{"id":"availability","g":"run","word":"Доступност","text":"Да ли људи могу да користе услугу кад им затреба, често мерено као uptime.","also":["доступност","доступности","availability","high availability","висока доступност"]},{"id":"downtime","g":"run","word":"Downtime","text":"Време кад услуга не ради или је искључена, планирано или не.","also":["down time","време застоја"]},{"id":"errorbudget","g":"run","word":"Буџет грешака (error budget)","text":"Мала количина отказа коју дозвољава твој циљ поузданости. Док га још има, можеш да ризикујеш са изменама; кад се потроши, успориш.","also":["буџет грешака","error budget","error budgets"]},{"id":"outage","g":"run","word":"Прекид у раду (outage)","text":"Време кад услуга не ради или је тешко покварена за кориснике.","also":["прекид у раду","прекиди у раду","outage","outages"]},{"id":"degraded","g":"run","word":"Деградирана услуга","text":"Ради, али лоше: споро, или са неким деловима који не раде.","also":["деградирана услуга","деградиран","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Праћење (monitoring)","text":"Аутоматско посматрање услуге све време, да се проблеми примете, по могућству пре него што их корисници виде.","also":["праћење","мониторинг","monitoring"]},{"id":"observability","g":"run","word":"Уочљивост (observability)","text":"Колико добро можеш споља да сазнаш шта се дешава унутар система, помоћу његових дневника, бројева и трагова.","also":["уочљивост","опсервабилност","observability","o11y"]},{"id":"log","g":"run","word":"Лог (дневник)","text":"Дневник који програм стално води о томе шта ради, а користи се да се открије шта је пошло по злу.","also":["лог","лога","логови","логове","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Траг (trace)","text":"Запис како један захтев путује кроз различите делове система, корак по корак, и показује где је успорио.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Кашњење (latency)","text":"Колико времена треба да нешто одговори, као чекање између клика и појављивања странице.","also":["латенција","latency"]},{"id":"alert","g":"run","word":"Аларм","text":"Аутоматска порука да нешто захтева пажњу, као сајт који не одговара.","also":["аларм","аларма","аларми","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Замор од аларма","text":"Кад има толико аларма да их људи почну занемаривати, укључујући важне.","also":["замор од аларма","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Контролна табла (dashboard)","text":"Екран који једним погледом показује најважније бројеве и стања.","also":["контролна табла","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Хитно дозивање (paging)","text":"Хитно позивање или буђење дежурне особе због проблема.","also":["хитно дозивање","paging","paged"]},{"id":"escalation","g":"run","word":"Ескалација","text":"Укључивање некога са више вештине или овлашћења кад се проблем не може решити на тренутном нивоу, или не довољно брзо.","also":["ескалација","ескалирати","ескалирано","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Тријажа","text":"Брзо сортирање пристиглих проблема по хитности и важности, да се прво збрине оно најгоре.","also":["тријажа","triage","triaged"]},{"id":"impact","g":"run","word":"Утицај (impact)","text":"Колико нешто утиче на људе: колико њих и колико тешко.","noTip":1},{"id":"urgency","g":"run","word":"Хитност","text":"Колико брзо нешто мора да се реши. Утицај и хитност заједно одређују приоритет.","noTip":1},{"id":"plevels","g":"run","word":"Нивои приоритета (P1, P2…)","text":"Ознаке колико је проблем хитан. P1 је најозбиљнији и захтева акцију одмах.","also":["P1","P2","P3","P4","нивои приоритета"]},{"id":"queue","g":"run","word":"Ред тикета","text":"Листа захтева и инцидената који чекају да буду преузети.","also":["ред тикета","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Прва и друга линија","text":"Нивои подршке: прва линија прима позив и поправља једноставне ствари; друга линија има дубља знања за теже. Зову се и tier 1 и tier 2.","also":["прва линија","друга линија","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Командант инцидента","text":"Једна особа која води одговор на инцидент, да сви знају ко одлучује и ко шта ради.","also":["командант инцидента","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Време одзива","text":"Колико прође док неко први пут не преузме захтев или инцидент.","also":["време одзива","response time","response times"]},{"id":"resolution","g":"run","word":"Време решавања","text":"Колико траје да се захтев или инцидент у потпуности реши, од пријаве до поправке.","also":["време решавања","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Просечно време опоравка (MTTR)","text":"У просеку, колико траје да услуга поново проради пошто се поквари. MTTR може значити мало различите ствари, па реци шта меришеш.","also":["MTTR","просечно време опоравка","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Просечно време између отказа (MTBF)","text":"У просеку, колико дуго услуга ради пре него што се нешто поквари.","also":["MTBF","просечно време између отказа","mean time between failures"]},{"id":"cmdb","g":"run","word":"База конфигурација (CMDB)","text":"Списак свих конфигурационих ставки и како су повезане, да видиш шта од чега зависи.","also":["CMDB","база конфигурација","configuration management database"]},{"id":"asset","g":"run","word":"Средство (asset)","text":"Све вредно што поседујеш или плаћаш да би услуга радила, као лаптоп, лиценца за софтвер или домен.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Планирање капацитета","text":"Брига да буде довољно рачунарске снаге, складишта и људи за оно што долази.","also":["планирање капацитета","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Скалирање","text":"Прилагођавање већем броју корисника тако што машини дајеш више снаге (scaling up) или додајеш још машина (scaling out).","also":["скалирање","scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Континуитет пословања","text":"Планови да се важне ствари наставе кад нешто велико пође по злу, као губитак канцеларије, кључног добављача или рачунара.","also":["континуитет пословања","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Опоравак од катастрофе (DR)","text":"План и алати да се услуга врати после нечег озбиљног, као губитак целог центра података.","also":["DR","опоравак од катастрофе","disaster recovery"]},{"id":"rto","g":"run","word":"Циљано време опоравка (RTO)","text":"Најдуже што услуга сме да буде ван погона после катастрофе пре него што мора поново да ради.","also":["RTO","циљано време опоравка","recovery time objective"]},{"id":"rpo","g":"run","word":"Циљана тачка опоравка (RPO)","text":"Колико недавних података можеш себи да дозволиш да изгубиш, мерено временом. RPO од сат времена значи резервне копије бар сваког сата.","also":["RPO","циљана тачка опоравка","recovery point objective"]},{"id":"redundancy","g":"run","word":"Редундантност","text":"Спремне резерве, као други сервер, да један отказ не заустави услугу.","also":["редундантност","редундантан","redundancy"]},{"id":"failover","g":"run","word":"Failover","text":"Аутоматско прелажење на резервни систем кад уобичајени откаже.","also":["fail over","аутоматско преузимање"]},{"id":"spof","g":"run","word":"Појединачна тачка отказа","text":"Један део који са собом сруши све кад се поквари, јер нема резерве.","also":["појединачна тачка отказа","јединствена тачка отказа","single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Прозор за одржавање","text":"Планирано време кад услуга може да буде заустављена или спора ради одржавања, најављено корисницима унапред.","also":["прозор за одржавање","maintenance window","maintenance windows","planned maintenance","планирано одржавање"]},{"id":"handover","g":"run","word":"Примопредаја","text":"Предавање посла, знања и одговорности другој особи или тиму, да се ништа не изгуби.","also":["примопредаја","handover","handovers"]},{"id":"kb","g":"run","word":"База знања","text":"Збирка чланака помоћи и одговора, за кориснике и за тим.","also":["база знања","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Задовољство корисника (CSAT)","text":"Оцена корисника која показује колико су били задовољни, често тражена пошто се захтев затвори.","also":["CSAT","задовољство корисника","customer satisfaction"]},{"id":"supplier","g":"run","word":"Добављач","text":"Спољна компанија на коју се ослањаш, као твој пружалац хостинга. Зове се и vendor или трећа страна.","also":["добављач","добављачи","добављача","supplier","suppliers","vendor","vendors","third party","трећа страна"],"noTip":1},{"id":"retire","g":"run","word":"Гашење услуге","text":"Трајно искључивање услуге, на безбедан начин: обавештавање њених корисника, брига о њеним подацима и приступу и заустављање њених трошкова.","also":["гашење услуге","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Крај животног века (EOL)","text":"Кад производ престане да добија ажурирања или подршку од произвођача, па треба да се замени.","also":["EOL","крај животног века","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Сајбер безбедност","text":"Заштита система и података од упада, крађе или оштећења.","also":["сајбер безбедност","кибернетичка безбедност","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Аутентификација","text":"Провера ко је неко, обично лозинком или кодом. Често се скраћује authn.","also":["аутентификација","аутентикација","authentication","authn"]},{"id":"authz","g":"sec","word":"Ауторизација","text":"Провера шта је некоме дозвољено да ради кад већ знаш ко је. Често се скраћује authz.","also":["ауторизација","authz","authorization"]},{"id":"mfa","g":"sec","word":"Вишефакторска аутентификација (MFA)","text":"Пријава са два или више доказа, као лозинка плус код на телефону. Зове се и двофакторска (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","двофакторска аутентификација"]},{"id":"sso","g":"sec","word":"Јединствена пријава (SSO)","text":"Пријава једном да уђеш у много система, као када свуда користиш свој радни налог.","also":["SSO","јединствена пријава","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Менаџер лозинки","text":"Апликација која прави јаке лозинке и памти их уместо тебе.","also":["менаџер лозинки","password manager","password managers"]},{"id":"secret","g":"sec","word":"Тајна (secret)","text":"Лозинка, кључ или други приватни код који програм користи да уђе негде. Никад се не сме делити нити уписивати у код.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API кључ","text":"Тајни код који програму омогућава да користи API друге услуге и показује ко је користи (и плаћа).","also":["API кључ","API кључеви","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Приступни токен","text":"Привремена пропусница која доказује да програм сме да уђе, да му не треба твоја лозинка сваки пут. Није исто што и AI токен.","also":["приступни токен","приступни токени","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Шифровање","text":"Претварање информација у нечитљив облик, тако да их може прочитати само неко са правим кључем.","also":["шифровање","шифрован","шифровано","encryption","encrypted","encrypt","енкрипција"]},{"id":"https","g":"sec","word":"HTTPS","text":"Безбедан начин на који путују веб странице, који се види по катанцу у прегледачу, да их нико између не може прочитати нити променити."},{"id":"cert","g":"sec","word":"SSL/TLS сертификат","text":"Дигитална лична карта којом сајт доказује ко је и може да користи HTTPS. Истиче, па се мора обновити.","also":["TLS сертификат","SSL сертификат","сертификат","сертификати","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Дозволе","text":"Правила ко сме шта да види или промени.","also":["дозвола","дозволе","дозволама","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Најмање привилегија","text":"Давање свакој особи или програму само приступа који им је заиста потребан, и то само док им треба.","also":["најмање привилегија","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Контрола приступа по улогама (RBAC)","text":"Давање приступа по улози, као гледалац или уредник, а не за сваку особу посебно.","also":["RBAC","контрола приступа по улогама","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Рањивост","text":"Слабост коју неко може да искористи да провали или нанесе штету.","also":["рањивост","рањивости","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Слабост за коју нападачи знају пре него што су произвођачи имали времена да је поправе.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Штетан софтвер, као вируси, направљен да оштети, шпијунира или краде.","also":["малвер","злонамерни софтвер"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware који закључава твоје фајлове и тражи новац да их откључа. Добре резервне копије су најбоља одбрана.","also":["ransomware attack","рансомвер","откупни софтвер"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Лажне поруке које покушавају да те преваре да одаш лозинке или новац, или да отвориш нешто штетно.","also":["phishing email","phishing emails","фишинг"]},{"id":"socialeng","g":"sec","word":"Социјални инжењеринг","text":"Варање људи, а не рачунара, да дају приступ, као лажан позив из „IT подршке“."},{"id":"firewall","g":"sec","word":"Firewall","text":"Чувар који одлучује какав мрежни саобраћај сме да уђе или изађе.","also":["firewalls","заштитни зид"]},{"id":"vpn","g":"sec","word":"VPN","text":"Скраћено од виртуелна приватна мрежа: приватна, шифрована веза преко интернета, често коришћена за безбедан приступ радним системима.","also":["virtual private network","виртуелна приватна мрежа"]},{"id":"ddos","g":"sec","word":"Ускраћивање услуге (DoS, DDoS)","text":"Преплављивање услуге толиким лажним саобраћајем да је прави људи не могу да користе. DDoS значи да долази са много рачунара одједном.","also":["DoS","DDoS","denial of service","DDoS attack","ускраћивање услуге","DDoS напад"]},{"id":"pentest","g":"sec","word":"Тест пенетрације (pen test)","text":"Ангажовање пријатељских стручњака да покушају да провале, да се слабости нађу пре него што их нађу прави нападачи.","also":["тест пенетрације","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Безбедносна ревизија","text":"Пажљива провера колико је нешто добро заштићено, у односу на списак добрих пракси.","also":["безбедносна ревизија","безбедносни аудит","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Моделовање претњи","text":"Размишљање ко би могао да нападне нешто, како, и шта може да се уради да се то спречи.","also":["моделовање претњи","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Повреда података","text":"Кад приватне информације стигну до људи који не би требало да их имају, или се изгубе или промене без дозволе.","also":["повреда података","цурење података","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Лични подаци","text":"Свака информација о особи која се може препознати, као име, имејл адреса или локација. Зову се и PII.","also":["лични подаци","личних података","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Европски закон о личним подацима (Уједињено Краљевство има своју верзију): прикупљај само оно што ти треба, чувај то безбедно и дозволи људима да виде или обришу своје.","also":["General Data Protection Regulation","Општа уредба о заштити података"]},{"id":"dataprot","g":"sec","word":"Заштита података","text":"Правилна брига о личним подацима, у складу са законом.","also":["заштита података","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Политика приватности","text":"Јавна страница која каже које личне податке прикупљаш, зашто и шта радиш са њима.","also":["политика приватности","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Пристанак","text":"Јасно, слободно „да“ једне особе да се њени подаци користе на одређен начин. Особа може да га повуче у сваком тренутку.","also":["пристанак","сагласност","consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Мали фајл који сајт чува у твом прегледачу да би нешто запамтио, на пример да си пријављен. За неке је прво потребан твој пристанак.","also":["cookies","колачић","колачићи"],"noTip":1},{"id":"minimisation","g":"sec","word":"Минимизација података","text":"Прикупљање и чување само личних података који су заиста потребни за посао.","also":["минимизација података","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Чување података","text":"Колико дуго се подаци чувају пре брисања. Чување не дуже него што је потребно је безбедније, а често га захтева и закон.","also":["чување података","рок чувања","data retention","retention period"]},{"id":"anon","g":"sec","word":"Анонимизација","text":"Мењање података тако да се из њих више нико не може разумно препознати.","also":["анонимизација","анонимизовано","anonymisation","anonymised","anonymization","anonymous data","анонимни подаци"]},{"id":"pseudo","g":"sec","word":"Псеудонимизација","text":"Замена имена и других детаља шифрама, уз кључ који се држи одвојено да би се могли повезати назад. То су и даље лични подаци.","also":["псеудонимизација","псеудонимизовано","pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Уговор о обради података (DPA)","text":"Уговор који каже како добављач сме да рукује личним подацима у твоје име.","also":["DPA","уговор о обради података","data processing agreement"]},{"id":"dpia","g":"sec","word":"Процена утицаја на заштиту података (DPIA)","text":"Пажљива процена, пре него што почнеш, како план за коришћење личних података може да утиче на људе и како да се смање ризици.","also":["DPIA","процена утицаја на заштиту података","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Евиденција ревизије (audit log)","text":"Запис ко је шта урадио и када, да се радње могу накнадно проверити.","also":["евиденција ревизије","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Усклађеност (compliance)","text":"Придржавање закона, правила и стандарда који се на тебе односе, и могућност да то докажеш.","also":["усклађеност","усаглашеност","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Познат међународни стандард за управљање безбедношћу информација. Компаније могу бити сертификоване по њему.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Амерички извештај, који проверавају спољни ревизори, и показује да компанија исправно брине о подацима корисника.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Агент","text":"AI који сам ради на задатку: чита код, прави измене, покреће провере и јавља се назад. Његов рад се и даље проверава.","also":["агент","агента","агенти","агената","agent","agents"]},{"id":"token","g":"ai","word":"Токен","text":"Ситни комади текста које AI чита и пише, отприлике три четвртине речи сваки. Коришћење AI-ја се броји у токенима, па мање токена оставља више од твог плана.","also":["токен","токена","токени","токена","token","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Мала команда која се сама покреће у одређеном тренутку, на пример кад почне AI сесија, да тим чује твоје коментаре.","also":["hook","hook-ови","hook-а","hooks"]},{"id":"ai","g":"ai","word":"Вештачка интелигенција (AI)","text":"Рачунарски системи који раде ствари за које обично мислимо да су потребни људи, као писање, одговарање на питања или препознавање слика.","also":["AI","вештачка интелигенција","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Машинско учење (ML)","text":"Начин да рачунари уче обрасце из много примера, уместо да им се дају тачна правила.","also":["ML","машинско учење","machine learning"]},{"id":"model","g":"ai","word":"Модел","text":"Обучени „мозак“ AI система, направљен учењем из огромног броја примера. Модели се разликују по вештини, брзини и цени.","also":["модел","модела","модели","model","models","AI model","AI модел"],"noTip":1},{"id":"llm","g":"ai","word":"Велики језички модел (LLM)","text":"AI модел обучен на огромним количинама текста, па може да чита и пише језик.","also":["LLM","LLMs","велики језички модел","large language model"]},{"id":"genai","g":"ai","word":"Генеративни AI","text":"AI који ствара нове ствари, као текст, слике или код, а не само да их разврстава или препознаје.","also":["GenAI","generative AI","генеративни AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Програм са којим разговараш обичним језиком, куцањем или говором.","also":["chatbots","чатбот"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Оно што даш AI-ју: твоје питање или упутства, плус све што му пружиш. Јаснији промпти обично дају боље одговоре.","also":["prompts","промпт","промпти"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Вештина писања промптова који дају поуздане, корисне резултате.","also":["инжењеринг промптова"]},{"id":"sysprompt","g":"ai","word":"Системски промпт","text":"Позадинска упутства која AI добије пре почетка разговора, а одређују његову улогу и правила. Имају већу тежину од онога што ти куцаш.","also":["системски промпт","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Контекст","text":"Све што AI може да види док ради: упутства, твоје поруке, фајлове које је прочитао и раније одговоре.","noTip":1},{"id":"ctxwin","g":"ai","word":"Контекстни прозор","text":"Колико AI може да држи на уму одједном, мерено у токенима. Преко тога се старији делови одбацују или сажимају.","also":["контекстни прозор","context window","context windows"]},{"id":"session","g":"ai","word":"Сесија","text":"Један радни разговор са AI-јем, од почетка до краја. Нова сесија почиње са свежом меморијом.","also":["сесија","сесије","сесији","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Меморија","text":"Белешке које AI чува између сесија, да памти твоје склоности и раније одлуке.","noTip":1},{"id":"hallucination","g":"ai","word":"Халуцинација","text":"Кад AI каже нешто што звучи уверено, а измишљено је или погрешно. Проверавај важне чињенице.","also":["халуцинација","халуцинације","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Обучавање","text":"Обучавање модела тако што му се покаже огроман број примера, пре него што га ико користи.","also":["обучавање","тренирање","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Подаци за обучавање","text":"Примери из којих је модел учио. Његово знање стаје на датуму када су ти подаци прикупљени.","also":["подаци за обучавање","training data","training set"]},{"id":"cutoff","g":"ai","word":"Крајњи датум знања","text":"Датум када се завршава уграђено знање једног AI-ја. Неће знати за касније ствари осим ако их потражи.","also":["крајњи датум знања","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Фино подешавање (fine-tuning)","text":"Додатно обучавање постојећег модела на твојим примерима, да буде бољи у једном одређеном послу.","also":["фино подешавање","fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Инференција (inference)","text":"Стварно коришћење AI модела да би одговорио на нешто, за разлику од његовог обучавања.","also":["инференција","inference","model inference"]},{"id":"tooluse","g":"ai","word":"Коришћење алата","text":"AI који може да ради ствари, а не само да прича: покреће команде, чита фајлове или претражује веб, преко алата које му даје апликација.","also":["коришћење алата","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Подагент","text":"Помоћни AI коме главни AI преда мањи посао и од њега добије резултат назад.","also":["подагент","подагенти","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Мултиагентски","text":"Неколико AI-јева ради заједно на једном послу, сваки на свом делу, као мали тим.","also":["мултиагентски","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Аутономија","text":"Колико AI сме да уради сам пре него што мора да пита човека.","also":["аутономија","аутономан","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Човек у петљи (human in the loop)","text":"Укљученост човека који на кључним местима проверава или одобрава оно што AI ради. У AI-gile то си ти.","also":["човек у петљи","human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Заштитне ограде (guardrails)","text":"Ограничења и провере које држе радње AI-ја безбедним, као обавезно одобрење пре него што било шта оде уживо. Смањују ризик од грешака, али их не искључују.","also":["заштитне ограде","guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Генерисање уз претраживање (RAG)","text":"Омогућавање AI-ју да потражи ствари у твојим документима пре одговора, па се његови одговори ослањају на твоје чињенице.","also":["RAG","генерисање уз претраживање","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Претварање текста у листу бројева која чува његово значење, да рачунар може да нађе ствари сличног значења.","also":["embeddings","векторско представљање"]},{"id":"vectordb","g":"ai","word":"Векторска база података","text":"База направљена да претражује те листе бројева (embeddings), да нађе садржај сличног значења.","also":["векторска база података","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Заједнички начин да се алати и извори података прикључе на AI апликације, па их AI може користити.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Температура","text":"Подешавање колико су смели одговори једног AI-ја. Ниска даје постојаније, предвидљивије одговоре; висока разноврсније. Ни једно ни друго не значи да је увек у праву.","also":["температура","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Мултимодалан","text":"Способан да ради са више од једне врсте информација, као текст, слике и звук.","also":["мултимодалан","мултимодални","multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Евалуација (eval)","text":"Планирани тест колико добро AI ради на одабраним примерима, да можеш да упоређујеш моделе или промптове.","also":["евалуација","eval","evals"]},{"id":"bias","g":"ai","word":"Пристрасност (bias)","text":"Кад AI (или човек) неправедно нагиње на једну страну, често због онога из чега је учио.","also":["пристрасност","пристрасан","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Одговоран AI","text":"Коришћење AI-ја поштено, безбедно и искрено, при чему људи и даље одговарају за резултате.","also":["одговоран AI","етички AI","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Трик у коме скривена упутства у веб страници или фајлу покушавају да натерају AI да уради нешто што његов корисник није тражио.","also":["prompt injections","убацивање промпта"]},{"id":"ratelimit","g":"ai","word":"Ограничење учесталости (rate limit)","text":"Горња граница колико захтева смеш да пошаљеш услузи у одређеном времену. Ако је пређеш, мораш да чекаш.","also":["ограничење учесталости","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Ограничење коришћења","text":"Колико AI посла твој план дозвољава у неком периоду, а после тога рад се паузира или кошта више.","also":["ограничење коришћења","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Прављење софтвера углавном тако што AI-ју опишеш шта желиш, а он напише код.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Буџет","text":"Износ новца издвојен за нешто.","also":["буџет","буџета","буџети","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Процена трошка","text":"Најбоља претпоставка колико ће нешто коштати пре него што почнеш.","also":["процена трошка","процена трошкова","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Повраћај улагања (ROI)","text":"Шта добијеш назад у односу на оно што уложиш. Ако је позитивно, вредело је.","also":["ROI","повраћај улагања","return on investment"]},{"id":"tco","g":"money","word":"Укупан трошак власништва (TCO)","text":"Све што нешто заиста кошта током целог века, не само цена куповине: коришћење, подршка, надоградње и на крају гашење.","also":["TCO","укупан трошак власништва","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx и OpEx","text":"CapEx је новац потрошен унапред на ствари које задржаваш; OpEx је текућа потрошња, као месечни рачуни.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Претплата","text":"Редовно плаћање, обично месечно или годишње, да наставиш да користиш нешто.","also":["претплата","претплате","претплати","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Софтвер као услуга (SaaS)","text":"Софтвер који користиш на мрежи и плаћаш претплатом, док га произвођач води уместо тебе.","also":["SaaS","софтвер као услуга","software as a service"]},{"id":"payg","g":"money","word":"Плати колико користиш","text":"Плаћање само онога што користиш, као код рачунарства у облаку или AI токена.","also":["плати колико користиш","pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Прекорачење","text":"Коришћење преко онога што твој план укључује, што може коштати додатно.","also":["прекорачење","прекорачења","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Обавештење о наплати","text":"Порука кад потрошња или коришћење достигну ниво који изабереш. Упозорава те, али не зауставља увек даље трошкове.","also":["обавештење о наплати","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Бесплатни ниво","text":"Бесплатан ниво плаћене услуге, са ограничењима. Згодан за почетак.","also":["бесплатни ниво","бесплатни план","free tier","free plan"]},{"id":"pricing","g":"money","word":"Ценовни пакет","text":"Различити пакети које услуга продаје, сваки са својом ценом и ограничењима.","also":["ценовни пакет","ценовни пакети","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Лиценца","text":"Правила како смеш да користиш, умножаваш, мењаш или делиш нешто што је направио неко други, као софтвер, фонтове или слике.","also":["лиценца","лиценце","лиценци","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Отворени код (open source)","text":"Софтвер чији код свако може да чита, користи и често мења бесплатно, по правилима његове лиценце.","also":["отворени код","open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source лиценца","text":"Правила која долазе уз open source код. Неке дозвољавају скоро све (као MIT); неке траже да делиш и своје измене (као GPL).","also":["open source лиценца","open source лиценце","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Власнички (proprietary)","text":"Припада компанији и није слободан за умножавање или мењање. Супротно од open source.","also":["власнички","власнички софтвер","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Ауторско право","text":"Законско право аутора да контролише копије свог дела, укључујући код и текст.","also":["ауторско право","ауторска права","copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Интелектуална својина (IP)","text":"Идеје и творевине које закон третира као нечије власништво, као код, дизајни, имена и логотипи.","also":["IP","интелектуална својина","intellectual property"]},{"id":"tos","g":"money","word":"Услови коришћења","text":"Правила на која пристајеш кад користиш неку услугу.","also":["услови коришћења","услови услуге","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Уговор","text":"Писани договор између две стране који закон подржава.","also":["уговор","уговора","уговори","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Опис послова (SOW)","text":"Документ који тачно одређује који ће се посао радити, до када и за колико новца.","also":["SOW","опис послова","statement of work"]},{"id":"fixedprice","g":"money","word":"Фиксна цена","text":"Договорена цена за цео посао, ма колико трајао.","also":["фиксна цена","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Време и материјал","text":"Плаћање за стварно одрађене сате и стварно утрошене ствари, а не за одређену цену.","also":["T&M","време и материјал","time and materials"]},{"id":"invoice","g":"money","word":"Рачун (фактура)","text":"Рачун којим се тражи плаћање за урађен посао или испоручену робу.","also":["фактура","фактуре","фактуру","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Зависност од добављача (lock-in)","text":"Кад је прелазак са добављача толико тежак или скуп да од њега више не можеш да одеш.","also":["зависност од добављача","vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Набавка","text":"Поступак избора и куповине од добављача.","also":["набавка","набавке","набавци","procurement"]},{"id":"servicecredit","g":"money","word":"Кредит за услугу","text":"Повраћај новца или попуст који добијаш кад добављач прекрши SLA.","also":["кредит за услугу","service credit","service credits"]}]}};
